import json, base64, datetime, collections, re

def load(f):
    return [json.loads(l) for l in open(f)]

pats = {p['id']:p for p in json.load(open('patients.txt'))['resources']}
meds = {m['id']:m for m in load('Medication.ndjson')}
def medname(mid):
    m = meds.get(mid)
    if not m: return None
    for i in m.get('identifier',[]):
        if i['system'].endswith('mimic-medication-name'): return i['value']
    if m.get('text'): return m['text']
    return m.get('code',{}).get('coding',[{}])[0].get('code')

encs = {e['id']:e for e in load('Encounter.ndjson')}
