    ns=sorted(byp[p],key=lambda x:x['date'])
    seq=[]
    for n in ns:
        for l in n['text'].split('\n'):
            if l.startswith('Current medications'):
                ds=sorted(set(re.findall(QTD,l,re.I)))
                seq.append((n['date'][:10],tuple(x.lower() for x in ds),n['id']))
    if any(s[1] for s in seq):
        print('==',pats[p]['identifier'][0]['value'],p[:8])
        for s in seq: print('   ',s[0],s[1])
print()
print('--- outpatient MedicationRequests for QT drugs (long validity) ---')
