for m in sorted(mr,key=lambda x:x['authoredOn']):
    n=medname(m.get('medicationReference',{}).get('reference','').split('/')[-1])
    if not re.search(QTD,n,re.I): continue
    dr=m.get('dispenseRequest',{}).get('validityPeriod',{})
